/* Deterministic stardust: the very same particles travel into the exact glyph mask. */
(() => {
 'use strict';
 const cache=new Map(),clamp=n=>Math.max(0,Math.min(1,n)),ease=n=>{n=clamp(n);return n*n*(3-2*n);};
 function star(c,x,y,r){c.beginPath();c.moveTo(x-r,y);c.lineTo(x-r*.18,y-r*.18);c.lineTo(x,y-r);c.lineTo(x+r*.18,y-r*.18);c.lineTo(x+r,y);c.lineTo(x+r*.18,y+r*.18);c.lineTo(x,y+r);c.lineTo(x-r*.18,y+r*.18);c.closePath();c.fill();}
 function layout(text,size,maxWidth,y){const key=[text,size,maxWidth,y].join('|');if(cache.has(key))return cache.get(key);const mask=document.createElement('canvas');mask.width=1080;mask.height=600;const m=mask.getContext('2d',{willReadFrequently:true});m.font=`900 ${size}px Georgia,serif`;while(m.measureText(text).width>maxWidth&&size>24)m.font=`900 ${--size}px Georgia,serif`;m.textAlign='center';m.fillStyle='#fff';m.fillText(text,540,y);const width=m.measureText(text).width,x=540-width/2,pixels=m.getImageData(0,0,1080,600).data,points=[];for(let py=Math.max(0,Math.floor(y-size-10));py<Math.min(600,y+40);py+=4)for(let px=Math.max(0,Math.floor(x-4));px<Math.min(1080,x+width+4);px+=4){if(pixels[(py*1080+px)*4+3]<160)continue;const seed=((px*73+py*131)%997)/997,tx=px+(seed-.5)*3.8,ty=py+(((px*47+py*97)%983)/983-.5)*3.8;if(pixels[(Math.round(ty)*1080+Math.round(tx))*4+3]<160)continue;points.push({x:tx,y:ty,seed,birth:.02+.56*clamp((tx-x)/Math.max(1,width))+.12*seed});}const result={font:m.font,size,width,x,y,points};if(cache.size>12)cache.clear();cache.set(key,result);return result;}
 window.SANTA_STARDUST={draw(c,text,t,start,duration,options={}){if(!text||t<=start)return;const p=clamp((t-start)/duration),l=layout(text,options.size||300,options.maxWidth||930,options.y||440);c.save();c.globalCompositeOperation='screen';c.shadowColor='#ffdc7c';c.shadowBlur=8;
 // Loose individual stars rise into the letters; no rectangle wipes or opaque clouds.
 if(p<1){for(let i=0;i<72;i++){const q=(p*1.7+i/72)%1,edge=l.x+l.width*clamp(p*1.35),sx=130+(edge-130)*q+Math.sin(q*11+p*8)*(1-q)*65,sy=650+(l.y-l.size*.4-650)*q+Math.cos(q*13+p*5)*(1-q)*35;c.globalAlpha=(1-p*.6)*(.2+q*.7);c.fillStyle=i%3?'#ffdf70':'#fff8d3';star(c,sx,sy,i%13===0?8:2+i%3);}}
 c.shadowBlur=0;
 for(const dot of l.points){const local=options.immediate?1+p:(p-dot.birth)/.30;if(local<=0)continue;const f=ease(local),sx=130+dot.seed*190,sy=610+Math.sin(dot.seed*31)*55,bend=Math.sin(f*Math.PI)*Math.sin(dot.seed*19)*100,x=sx+(dot.x-sx)*f+bend,y=sy+(dot.y-sy)*f-Math.sin(f*Math.PI)*100;c.globalAlpha=Math.min(1,local*4)*(.7+.3*Math.sin(t*4+dot.seed*35));c.fillStyle=dot.seed>.7?'#fff9d0':'#ffd65c';c.beginPath();c.arc(x,y,.7+dot.seed*1.6,0,Math.PI*2);c.fill();}
 c.globalCompositeOperation='source-over';c.globalAlpha=options.immediate ? .12+.88*ease(p) : ease((p-.72)/.28);c.textAlign='center';c.font=l.font;c.lineJoin='round';c.shadowColor='#ffdd82';c.shadowBlur=20;const gold=c.createLinearGradient(0,l.y-l.size,0,l.y+15);gold.addColorStop(0,'#fff9d6');gold.addColorStop(.5,'#ffe582');gold.addColorStop(1,'#f9c444');c.fillStyle=gold;c.fillText(text,540,l.y);
 if(p>.7){c.shadowBlur=10;for(let i=0;i<25;i++){const dot=l.points[(i*137)%Math.max(1,l.points.length)];if(!dot)continue;c.globalAlpha=ease((p-.7)/.3)*Math.pow(Math.abs(Math.sin(t*2.5+i)),8);c.fillStyle='#fffbe4';star(c,dot.x,dot.y,i%6?3:9);}}c.restore();}};
 // Personal media stays in the tab. Local video audio is intentionally muted.
 window.SANTA_PORTRAIT={attach(prefix,onChange){
 const file=document.querySelector('#'+prefix+'-photo'),remove=document.querySelector('#'+prefix+'-photo-remove'),status=document.querySelector('#'+prefix+'-photo-status'),thumb=document.querySelector('#'+prefix+'-photo-thumb');
 let bitmap=null,video=null,url='',version=0,pending=false,videoEpoch=null;
 function release(){bitmap?.close();bitmap=null;if(video){video.pause();video.removeAttribute('src');video.load();video=null;}if(url)URL.revokeObjectURL(url);url='';videoEpoch=null;}
 function clear(){++version;pending=false;release();file.value='';thumb.removeAttribute('src');thumb.hidden=true;remove.hidden=true;status.textContent='Opcional. La foto o el video aparecerá al revelarse el nombre. Se procesa solo en tu dispositivo.';onChange();}
 const loaded=v=>new Promise((resolve,reject)=>{v.addEventListener('loadeddata',resolve,{once:true});v.addEventListener('error',()=>reject(new Error('Video no compatible. Usa un MP4 H.264.')),{once:true});});
 file.addEventListener('change',async()=>{const f=file.files[0];if(!f)return;const isVideo=f.type.startsWith('video/');if((!isVideo&&!['image/jpeg','image/png','image/webp'].includes(f.type))||f.size>(isVideo?60:12)*1048576){status.textContent='Elige una foto JPG, PNG o WebP de hasta 12 MB, o un video de hasta 60 MB.';file.value='';return;}
 const id=++version;pending=true;status.textContent='Preparando tu imagen…';onChange();try{release();url=URL.createObjectURL(f);
 if(isVideo){const v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';const ready=loaded(v);v.src=url;v.load();await ready;if(id!==version){v.pause();return;}if(!Number.isFinite(v.duration)||v.duration<.1)throw new Error('Este video no tiene una duración válida.');video=v;
 const poster=document.createElement('canvas');poster.width=180;poster.height=180;const pc=poster.getContext('2d'),scale=Math.max(180/v.videoWidth,180/v.videoHeight);pc.drawImage(v,(180-v.videoWidth*scale)/2,(180-v.videoHeight*scale)/2,v.videoWidth*scale,v.videoHeight*scale);thumb.src=poster.toDataURL('image/jpeg',.8);
 }else{const im=await createImageBitmap(f);if(id!==version){im.close();return;}bitmap=im;thumb.src=url;}
 thumb.hidden=false;remove.hidden=false;pending=false;status.textContent=isVideo?'Video preparado. Se mostrará sin sonido dentro del marco mágico del cielo.':'Foto preparada. Aparecerá junto al nombre dentro del marco mágico del cielo.';onChange();
 }catch(e){if(id===version){release();pending=false;status.textContent=e.message||'No se pudo abrir el archivo. Prueba con una foto o un MP4 H.264.';onChange();}}});remove.addEventListener('click',clear);
 const targetTime=(t,start)=>video?Math.min(Math.max(0,t-start),Math.max(0,video.duration-.06)):0;
 function rounded(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);}
 return {ready:()=>!pending,has:()=>!!(bitmap||video),play(){videoEpoch=null;},pause(){video?.pause();},async seekAt(t,start){if(!video)return;video.pause();const target=targetTime(t,start);if(Math.abs(video.currentTime-target)<.005)return;await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{video.removeEventListener('seeked',done);reject(new Error('No se pudo leer un cuadro del video. Usa otro MP4 o una foto.'));},7000);const done=()=>{clearTimeout(timer);resolve();};video.addEventListener('seeked',done,{once:true});video.currentTime=target;});},
 draw(c,t,start){const media=bitmap||video;if(!media||t<=start)return;const p=ease((t-start)/.8),x=540,y=860,w=636,h=486,r=38,mw=bitmap?.width||video.videoWidth,mh=bitmap?.height||video.videoHeight,scale=Math.max(w/mw,h/mh);c.save();c.translate(x,y-20*(1-p));c.scale(.88+.12*p,.88+.12*p);c.globalAlpha=p;rounded(c,-w/2,-h/2,w,h,r);c.save();c.clip();c.fillStyle='#fff8e5';c.fillRect(-w/2,-h/2,w,h);c.drawImage(media,-mw*scale/2,-mh*scale/2,mw*scale,mh*scale);c.restore();c.shadowColor='#ffe498';c.shadowBlur=24;c.strokeStyle='#fff0ae';c.lineWidth=7;rounded(c,-w/2,-h/2,w,h,r);c.stroke();c.shadowBlur=0;for(let i=0;i<24;i++){const angle=i*Math.PI*2/24;c.globalAlpha=p*(.3+.7*Math.abs(Math.sin(t*2+i)));c.fillStyle='#ffefb5';star(c,Math.cos(angle)*(w/2+20),Math.sin(angle)*(h/2+18),i%5?3:8);}c.restore();},
 syncPreview(t,start){if(!video)return;if(t<start){video.pause();videoEpoch=null;return;}if(videoEpoch===null){videoEpoch=t;video.currentTime=0;video.play().catch(()=>{});}},
 reset(){videoEpoch=null;video?.pause();if(video)video.currentTime=0;}};
 }};
})();
